    def authorize_searchos_judgment(
        self,
        *,
        reservation_ref: Mapping[str, Any],
        slot_id: str,
        candidate_window: Mapping[str, Any],
        read_custody_refs: Sequence[Mapping[str, Any]] = (),
        navigation_window: Sequence[Mapping[str, Any]] | None = None,
        reason: str = "neutral_model_owned_searchos_judgment",
    ) -> AuthorizedAction:
        from core.searchos_iterative_judgment_runtime import (
            build_searchos_judgment_request_v1,
            build_searchos_navigation_judgment_request_v1,
            charge_searchos_judgment_call,
        )

        if not self.state.searchos_state:
            raise RunKernelTransitionError("SearchOS judgment requires initialized state")
        try:
            state, charge = charge_searchos_judgment_call(
                self.state.searchos_state,
                reservation_ref=reservation_ref,
                slot_id=slot_id,
            )
            request_builder = (
                build_searchos_navigation_judgment_request_v1
                if _safe_mapping(state.get("policy_snapshot")).get(
                    "navigation_runtime_open"
                )
                is True
                and navigation_window is not None
                else build_searchos_judgment_request_v1
            )
            request = request_builder(
                state=state,
                slot_id=slot_id,
                charge_ref=charge,
                candidate_window=candidate_window,
                read_custody_refs=read_custody_refs,
                **(
                    {"navigation_window": navigation_window}
                    if request_builder is build_searchos_navigation_judgment_request_v1
                    else {}
                ),
            )
        except ValueError as exc:
            raise RunKernelTransitionError(str(exc)) from exc
        self.state.searchos_state = state
        return self.authorize(
            stage=SEARCHOS_JUDGMENT_STAGE,
            action_type=ActionType.SEARCHOS_JUDGMENT_DECIDE,
            reason=reason,
            inputs={
                "judgment_request": request,
                "charge_ref": charge,
            },
            expected_observation_type=ObservationType.SEARCHOS_JUDGMENT_DECIDED,
        )

    def authorize_searchos_navigation_selection(
        self,
        *,
        judgment_decision_ref: Mapping[str, Any],
        navigation_candidate: Mapping[str, Any],
        reason: str = "evaluate_bounded_searchos_navigation_selection",
    ) -> AuthorizedAction:
        from core.searchos_navigation_runtime import (
            build_navigation_selection_action_inputs,
        )

        if not self.state.searchos_state:
            raise RunKernelTransitionError(
                "navigation selection requires initialized SearchOS state"
            )
        current = _safe_mapping(self.state.searchos_state)
        if (
            current.get("run_id") != self.state.run_id
            or current.get("request_id") != self.state.request_id
        ):
            raise RunKernelTransitionError(
                "navigation selection SearchOS scope differs from RunKernel"
            )
        try:
            inputs = build_navigation_selection_action_inputs(
                self.state.searchos_state,
                judgment_decision_ref=judgment_decision_ref,
                navigation_candidate=navigation_candidate,
            )
        except ValueError as exc:
            raise RunKernelTransitionError(str(exc)) from exc
        return self.authorize(
            stage=SEARCHOS_NAVIGATION_SELECTION_STAGE,
            action_type=ActionType.SEARCHOS_NAVIGATION_SELECT,
            reason=reason,
            inputs=inputs,
            expected_observation_type=(
                ObservationType.SEARCHOS_NAVIGATION_SELECTED
            ),
        )

